```ts
function bossHpBar(hp: number, maxHp: number, width = 20): string {
  const ratio = maxHp > 0 ? Math.max(0, Math.min(1, hp / maxHp)) : 0;
  const filled = Math.round(ratio * width);
  const bar = "█".repeat(filled) + "░".repeat(width - filled);
  const color = ratio > 0.5 ? "\x1b[31m" : ratio > 0.25 ? "\x1b[33m" : "\x1b[35m";
  const reset = "\x1b[0m";
  return `${color}[${bar}] ${hp}/${maxHp}${reset}`;
}
