```ts
// code-actions/search.ts
import type { Snippet } from "./snippets.js";

/**
 * Normalize a string for search: lowercase and replace common
 * separators (dashes, underscores, dots, slashes) with spaces.
 * This lets "pi logs" match "pi-logs" and vice versa.
 */
export function normalizeForSearch(input: string): string {
  return input
    .toLowerCase()
    .replace(/[-_./\\]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

/**
 * Filter snippets by a search query. Both the query and each item's
 * searchable text are normalized, then a single substring check is done.
 */
export function filterSnippets(snippets: Snippet[], query: string): Snippet[] {
  const q = normalizeForSearch(query);
  if (!q) return snippets;

  return snippets.filter((s) => {
    const haystack = normalizeForSearch(`${s.preview} ${s.language} ${s.source}`);
    return haystack.includes(q);
  });
}
```

This drops the tokenization, scoring, and `rankedFilterItems` entirely. The one behavior we lose is that `pi-l` no longer ranks `pi-logs` above `pi logs` — but since both now match on the normalized substring, they'll both appear (in original order). If you want to keep that ordering preference without full scoring, I can add a tiny tie-breaker later; for now this is the simple version you asked for.

