import type { ExtensionAPI } from "@mariozechner/pi-extensions";
import { pickSnippet } from "./ui.js";
import { collectSnippets } from "./snippets.js";

const HELP_TEXT = `Usage:
  /code          Pick a snippet (Enter=copy, Tab/Right=insert)
  /code all      Include older messages
  /code run      Run the selected snippet`;

interface ParsedArgs {
  includeAll: boolean;
  run: boolean;
}

function parseArgs(args: string[]): ParsedArgs {
  const includeAll = args.includes("all");
  const run = args.includes("run");
  return { includeAll, run };
}

export default function register(api: ExtensionAPI) {
  api.registerCommand({
    name: "code",
    description: "Pick a code snippet from assistant messages",
    async handler(args: string[]) {
      const { includeAll, run } = parseArgs(args);

      if (args.includes("help") || args.includes("-h")) {
        api.notify(HELP_TEXT);
        return;
      }

      const snippets = collectSnippets(api, { includeAll });
      if (snippets.length === 0) {
        api.notify("No code snippets found in assistant messages.");
        return;
      }

      await pickSnippet(api, snippets, { run });
    },
  });
}
```

## 3. Make `collectSnippets` unit-testable

