```ts
// code-actions/snippets.ts (add)
import type { ExtensionAPI } from "@mariozechner/pi-extensions";

export interface CollectOptions {
  includeAll: boolean;
}

/**
 * Collect snippets from assistant messages. Kept separate from the UI
 * so it can be unit-tested without a TUI.
 */
export function collectSnippets(
  api: ExtensionAPI,
  opts: CollectOptions
): Snippet[] {
  const messages = opts.includeAll
    ? api.getMessages()
    : api.getRecentMessages();

  const snippets: Snippet[] = [];
  for (const msg of messages) {
    if (msg.role !== "assistant") continue;
    const text = typeof msg.content === "string" ? msg.content : "";
    snippets.push(...extractSnippets(text, msg.timestamp));
  }
  // Most recent first
  return snippets.reverse();
}
```

Then `ui.ts` no longer needs to know about message collection — it just receives the already-collected `snippets` array (as shown in the `index.ts` handler above).

