.pi-status-model {
  min-width: 0;                 /* allow grid/flex child to shrink below content size */
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  /* shrink aggressively so the footer holds one line longer */
  flex: 0 1 auto;               /* if it's in a flex context */
