// Fires only when pct crosses the threshold upward (prev < 90 <= current).
export function crossedContextThreshold(prevPct: number | null, pct: number, threshold = 90): boolean {
  if (prevPct === null) return false; // no baseline yet — don't toast on first render
  return prevPct < threshold && pct >= threshold;
}
```

Keeping the threshold as a parameter (default 90) means the test can exercise other values without touching the constant.

**2. `src/taskpane/status-bar.ts`** — track the previous percentage and fire the toast on the crossing:

