I'll simplify `search.ts` to drop the scoring and just do a normalized `includes()` check.

```ts
// code-actions/search.ts

/**
 * Normalize a string for search: lowercase and replace any
 * non-alphanumeric character with a space. This makes the search
 * separator-insensitive (e.g. "pi logs" matches "pi-logs").
 */
export function normalizeForSearch(value: string): string {
  return value.toLowerCase().replace(/[^a-z0-9]+/g, " ");
}

/**
 * Filter items by a query using a single normalized substring check.
 * An empty query returns all items.
 */
export function filterItems<T extends { label: string }>(
  items: T[],
  query: string,
): T[] {
  const q = normalizeForSearch(query).trim();
  if (!q) return items;
  return items.filter((item) => normalizeForSearch(item.label).includes(q));
}
```

