## 1. `code-actions/snippets.ts` — simplify `collectSnippets`

Remove the timestamp sort; just walk branch entries in order and extract.

```ts
import type { BranchEntry } from "../types";
import { extractFencedBlocks, extractInlineSnippets, shouldIncludeInlineSnippet } from "./extract";

export interface Snippet {
  code: string;
  preview: string;
  timestamp: number;
  type: "fenced" | "inline";
}

export function collectSnippets(entries: BranchEntry[]): Snippet[] {
  const snippets: Snippet[] = [];

  for (const entry of entries) {
    if (entry.role !== "assistant") continue;
    const text = entry.content ?? "";

    for (const block of extractFencedBlocks(text)) {
      snippets.push({
        code: block,
        preview: getSnippetPreview(block),
        timestamp: entry.timestamp,
        type: "fenced",
      });
    }

    for (const inline of extractInlineSnippets(text)) {
      if (!shouldIncludeInlineSnippet(inline)) continue;
      snippets.push({
        code: inline,
        preview: getSnippetPreview(inline),
        timestamp: entry.timestamp,
        type: "inline",
      });
    }
  }

  return snippets;
}

export function getSnippetPreview(code: string): string {
  const firstLine = code.split("\n").find((l) => l.trim().length > 0) ?? "";
  return firstLine.trim();
}
```

