## 1. Simplify `search.ts`

Replace the scoring/ranking logic with a single normalized `includes()` check:

```ts
import type { SelectItem } from "@mariozechner/pi-tui";

function normalize(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
}

export function buildSearchIndex(_snippets: unknown, _items: SelectItem[]): void {
  // no-op, kept for call-site compatibility
}

export function rankedFilterItems(query: string, items: SelectItem[]): SelectItem[] {
  const q = normalize(query);
  if (!q) return items;
  return items.filter((item) => normalize(item.label).includes(q));
}
```

Notes:
- `normalize` lowercases and collapses every non-alphanumeric run (spaces, `_`, `-`, `(`, `)`, etc.) into a single space — so `foo_bar` matches `foo bar`.
- `buildSearchIndex` becomes a no-op so you don't have to touch the call site in `ui.ts`. If you'd rather, delete it and drop the `buildSearchIndex(...)` line in `ui.ts` too.
